import java.util.*;

class LogPolicy {
    static String levelOf(String event) {
        return switch (event) {
            case "verbose_state" -> "DEBUG";
            case "request_success", "validation_rejected" -> "INFO";
            case "retry_recovered" -> "WARN";
            case "dependency_failed" -> "ERROR";
            default -> "ERROR";
        };
    }
}

class MiniLogger {
    /**
     * SLF4Jと同じ約束で1件を記録する。
     * `{}` へ値を順に埋め、**最後の引数が Throwable なら**その原因の連鎖も残す。
     */
    static void log(String level, String message, Object... args) {
        Throwable error = null;
        int valueCount = args.length;
        if (valueCount > 0 && args[valueCount - 1] instanceof Throwable last) {
            error = last;
            valueCount--;
        }
        StringBuilder line = new StringBuilder(level).append(' ');
        int used = 0;
        int from = 0;
        int hole;
        while ((hole = message.indexOf("{}", from)) >= 0) {
            line.append(message, from, hole);
            line.append(used < valueCount ? args[used] : "{}");
            used++;
            from = hole + 2;
        }
        line.append(message.substring(from));
        System.out.println(line);
        for (Throwable t = error; t != null; t = t.getCause()) {
            System.out.println("caused-by=" + t.getClass().getName() + ": " + t.getMessage());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String event = sc.next();
        String orderId = sc.next();
        String failure = sc.next();
        Throwable error = null;
        if (failure.equals("db")) {
            error = new IllegalStateException("outbox write failed",
                    new RuntimeException("connection refused"));
        } else if (failure.equals("illegal")) {
            error = new IllegalArgumentException("count must be positive");
        }
        String level = LogPolicy.levelOf(event);
        if (error == null) {
            MiniLogger.log(level, "event={} orderId={}", event, orderId);
        } else {
            MiniLogger.log(level, "event={} orderId={}", event, orderId, error);
        }
    }
}

