        Map<String, String> safe = sanitize(input);
        StringJoiner line = new StringJoiner(" ");
        safe.forEach((key, value) -> line.add(key + "=" + value));
        line.add("dropped=" + (input.size() - safe.size()));
        System.out.println(line);
