import java.util.*;

record Rule(String prefix, String level) { }

public class Main {
    static final List<String> LEVELS = List.of("TRACE", "DEBUG", "INFO", "WARN", "ERROR");

    static String effectiveLevel(String logger, String root, List<Rule> rules) {
        String selected = root;
        int longest = -1;
        for (Rule rule : rules) {
            boolean matches = logger.equals(rule.prefix())
                    || logger.startsWith(rule.prefix() + ".");
            if (matches && rule.prefix().length() > longest) {
                selected = rule.level();
                longest = rule.prefix().length();
            }
        }
        return selected;
    }

    static boolean enabled(String configured, String event) {
        return LEVELS.indexOf(event) >= LEVELS.indexOf(configured);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String root = sc.next();
        int n = sc.nextInt();
        List<Rule> rules = new ArrayList<>();
        for (int i = 0; i < n; i++) rules.add(new Rule(sc.next(), sc.next()));
        int m = sc.nextInt();
        int emitted = 0;
        for (int i = 0; i < m; i++) {
            String logger = sc.next(), level = sc.next(), message = sc.next();
            if (enabled(effectiveLevel(logger, root, rules), level)) {
                System.out.println(logger + " " + message);
                emitted++;
            }
        }
        if (emitted == 0) System.out.println("NONE");
    }
}

