import java.util.*;

record Deployment(int time, String version) { }
record IncidentLog(int time, String requestId, String level, String event, int sequence) { }

public class Main {
    static IncidentLog firstError(String target, List<IncidentLog> logs) {
        return logs.stream()
                .filter(log -> log.requestId().equals(target))
                .filter(log -> log.level().equals("ERROR"))
                .sorted(Comparator.comparingInt(IncidentLog::time)
                        .thenComparingInt(IncidentLog::sequence))
                .findFirst().orElse(null);
    }

    static Deployment latestBefore(int time, List<Deployment> deployments) {
        return deployments.stream()
                .filter(deployment -> deployment.time() <= time)
                .max(Comparator.comparingInt(Deployment::time))
                .orElse(null);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String target = sc.next();
        int d = sc.nextInt();
        List<Deployment> deployments = new ArrayList<>();
        for (int i = 0; i < d; i++) deployments.add(new Deployment(sc.nextInt(), sc.next()));
        int n = sc.nextInt();
        List<IncidentLog> logs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            logs.add(new IncidentLog(sc.nextInt(), sc.next(), sc.next(), sc.next(), i));
        }

        IncidentLog error = firstError(target, logs);
        if (error == null) {
            System.out.println("firstError=NONE");
            System.out.println("hypothesis=NONE");
            return;
        }
        System.out.println("firstError=" + error.event() + "@" + error.time());
        Deployment deployment = latestBefore(error.time(), deployments);
        System.out.println(deployment == null ? "hypothesis=NONE"
